    # ------------------------------------------------------------------
    # Final integrity safeguard: a room must never be over capacity.
    # The partial unique indexes above stop a *bed* from being double
    # booked, and the application locks room rows before allocating, but
    # this trigger provides a database-level guarantee that survives any
    # code path (manual SQL, future features, bugs).
    # ------------------------------------------------------------------
    op.execute(
        """
        CREATE OR REPLACE FUNCTION check_room_capacity()
        RETURNS trigger AS $$
        DECLARE
            room_capacity integer;
            bed_count integer;
        BEGIN
            -- Only active allocations consume a bed.
            IF NEW.status <> 'active' THEN
                RETURN NEW;
            END IF;

            SELECT capacity INTO room_capacity FROM rooms WHERE id = NEW.room_id;
            IF room_capacity IS NULL THEN
                RETURN NEW;
            END IF;

            SELECT count(*) INTO bed_count
            FROM room_allocations
            WHERE room_id = NEW.room_id
              AND status = 'active'
              AND id <> COALESCE(NEW.id, -1);

            IF bed_count >= room_capacity THEN
                RAISE EXCEPTION
                    'Room % is already at full capacity (% beds)',
                    NEW.room_id, room_capacity
                    USING ERRCODE = '23514';
            END IF;

            RETURN NEW;
        END;
        $$ LANGUAGE plpgsql;
        """
    )
    op.execute(
        """
        CREATE TRIGGER trg_room_capacity
        BEFORE INSERT OR UPDATE ON room_allocations
        FOR EACH ROW EXECUTE FUNCTION check_room_capacity();
        """
    )


